using System;
using System.Configuration;
using System.Data.SqlClient;
using Customization;

namespace HeritageFabrics.Setup
{
    /// <summary>
    /// Creates the UserAuditTrail Generic Inquiry via direct SQL.
    /// GI XML files are silently ignored for new GIs (fabricated GUIDs
    /// don't match any existing GIDesign record). This plugin inserts
    /// directly into GIDesign/GITable/GIResult/GIWhere/GISort/GIFilter tables.
    /// </summary>
    public class UserAuditTrailGISetup : CustomizationPlugin
    {
        private const string GI_NAME = "UserAuditTrail";
        private const string SCREEN_ID = "GI000000"; // generic GI screen

        public override void UpdateDatabase()
        {
            try
            {
                var cs = ConfigurationManager.ConnectionStrings["ProjectX"];
                if (cs == null) { WriteLog("[UserAuditTrailGI] No connection string — skipping"); return; }
                string connStr = cs.ConnectionString + ";TrustServerCertificate=True";

                using (var conn = new SqlConnection(connStr))
                {
                    conn.Open();

                    // Check if GI already exists
                    Guid? existingId = FindGI(conn, GI_NAME);
                    Guid designId;

                    if (existingId.HasValue)
                    {
                        designId = existingId.Value;
                        WriteLog("[UserAuditTrailGI] GI already exists (DesignID=" + designId + ") — rebuilding child rows");
                        // Clear child rows for rebuild
                        ClearChildren(conn, designId);
                    }
                    else
                    {
                        designId = Guid.NewGuid();
                        WriteLog("[UserAuditTrailGI] Creating new GI (DesignID=" + designId + ")");
                        InsertDesign(conn, designId);
                    }

                    // Insert table reference
                    InsertTable(conn, designId);

                    // Insert result columns
                    InsertResults(conn, designId);

                    // Insert WHERE conditions (filter bindings)
                    InsertWhereConditions(conn, designId);

                    // Insert sort
                    InsertSort(conn, designId);

                    // Insert filter parameters
                    InsertFilters(conn, designId);

                    WriteLog("[UserAuditTrailGI] GI setup complete — " + GI_NAME);
                }
            }
            catch (Exception ex)
            {
                WriteLog("[UserAuditTrailGI] ERROR: " + ex.GetType().FullName + ": " + ex.Message);
                if (ex.InnerException != null)
                    WriteLog("[UserAuditTrailGI] Inner: " + ex.InnerException.Message);
            }
        }

        private Guid? FindGI(SqlConnection conn, string name)
        {
            using (var cmd = new SqlCommand("SELECT DesignID FROM GIDesign WHERE Name = @Name AND CompanyID = 2", conn))
            {
                cmd.Parameters.AddWithValue("@Name", name);
                var result = cmd.ExecuteScalar();
                return result != null && result != DBNull.Value ? (Guid?)result : null;
            }
        }

        private void ClearChildren(SqlConnection conn, Guid designId)
        {
            string[] tables = { "GITable", "GIResult", "GIWhere", "GISort", "GIFilter", "GIRelation", "GIOn", "GIGroupBy" };
            foreach (var table in tables)
            {
                using (var cmd = new SqlCommand(string.Format("DELETE FROM {0} WHERE DesignID = @ID AND CompanyID = 2", table), conn))
                {
                    cmd.Parameters.AddWithValue("@ID", designId);
                    int rows = cmd.ExecuteNonQuery();
                    if (rows > 0) WriteLog("  Cleared " + rows + " rows from " + table);
                }
            }
        }

        private void InsertDesign(SqlConnection conn, Guid designId)
        {
            string sql = @"
                INSERT INTO GIDesign (CompanyID, DesignID, Name, ScreenID, FilterColCount, PageSize,
                    ExportTop, NewRecordCreationEnabled, MassDeleteEnabled, AutoConfirmDelete,
                    MassRecordsUpdateEnabled, MassActionsOnRecordsEnabled, ExposeViaOData, ExposeViaMobile)
                VALUES (2, @ID, @Name, @ScreenID, 4, 200, 0, 0, 0, 0, 0, 0, 1, 0)";
            using (var cmd = new SqlCommand(sql, conn))
            {
                cmd.Parameters.AddWithValue("@ID", designId);
                cmd.Parameters.AddWithValue("@Name", GI_NAME);
                cmd.Parameters.AddWithValue("@ScreenID", SCREEN_ID);
                cmd.ExecuteNonQuery();
            }
        }

        private void InsertTable(SqlConnection conn, Guid designId)
        {
            string sql = @"
                INSERT INTO GITable (CompanyID, DesignID, Alias, Name)
                VALUES (2, @ID, 'AuditHistory', 'PX.SM.AuditHistory')";
            using (var cmd = new SqlCommand(sql, conn))
            {
                cmd.Parameters.AddWithValue("@ID", designId);
                cmd.ExecuteNonQuery();
            }
        }

        private void InsertResults(SqlConnection conn, Guid designId)
        {
            // Result columns: ScreenID, Operation, ChangeDate, TableName, BatchID, ChangeID, CombinedKey, ModifiedFields, UserID
            var columns = new[]
            {
                new { LineNbr = 1, Field = "ScreenID", Caption = "Screen ID", Width = 100, SortOrder = 2 },
                new { LineNbr = 2, Field = "Operation", Caption = "Operation", Width = 80, SortOrder = 3 },
                new { LineNbr = 3, Field = "ChangeDate", Caption = "Change Date", Width = 160, SortOrder = 1 },
                new { LineNbr = 4, Field = "TableName", Caption = "Table Name", Width = 140, SortOrder = 4 },
                new { LineNbr = 5, Field = "BatchID", Caption = "Batch ID", Width = 80, SortOrder = 5 },
                new { LineNbr = 6, Field = "ChangeID", Caption = "Change ID", Width = 80, SortOrder = 6 },
                new { LineNbr = 7, Field = "CombinedKey", Caption = "Record Keys", Width = 200, SortOrder = 7 },
                new { LineNbr = 8, Field = "ModifiedFields", Caption = "Modified Fields", Width = 300, SortOrder = 8 },
                new { LineNbr = 9, Field = "UserID", Caption = "User", Width = 140, SortOrder = 0 },
            };

            foreach (var col in columns)
            {
                string sql = @"
                    INSERT INTO GIResult (CompanyID, DesignID, LineNbr, SortOrder, IsActive, ObjectName, Field,
                        SchemaField, Width, IsVisible, DefaultNav, QuickFilter, FastFilter, Caption)
                    VALUES (2, @ID, @LineNbr, @SortOrder, 1, 'AuditHistory', @Field,
                        NULL, @Width, 1, @DefaultNav, 0, @FastFilter, @Caption)";
                using (var cmd = new SqlCommand(sql, conn))
                {
                    cmd.Parameters.AddWithValue("@ID", designId);
                    cmd.Parameters.AddWithValue("@LineNbr", col.LineNbr);
                    cmd.Parameters.AddWithValue("@SortOrder", col.SortOrder);
                    cmd.Parameters.AddWithValue("@Field", col.Field);
                    cmd.Parameters.AddWithValue("@Width", col.Width);
                    cmd.Parameters.AddWithValue("@DefaultNav", col.LineNbr == 1 ? 1 : 0);
                    cmd.Parameters.AddWithValue("@FastFilter", col.LineNbr <= 4 || col.LineNbr == 9 ? 1 : 0);
                    cmd.Parameters.AddWithValue("@Caption", col.Caption);
                    cmd.ExecuteNonQuery();
                }
            }
        }

        private void InsertWhereConditions(SqlConnection conn, Guid designId)
        {
            // WHERE: ScreenID = @ScreenFilter AND ChangeDate >= @FromDate AND ChangeDate <= @ToDate
            var conditions = new[]
            {
                new { LineNbr = 1, DataFieldName = "AuditHistory.ScreenID", Condition = "E ", Value1 = "@ScreenFilter", Operation = "A" },
                new { LineNbr = 2, DataFieldName = "AuditHistory.ChangeDate", Condition = "GE", Value1 = "@FromDate", Operation = "A" },
                new { LineNbr = 3, DataFieldName = "AuditHistory.ChangeDate", Condition = "LE", Value1 = "@ToDate", Operation = "A" },
            };

            foreach (var cond in conditions)
            {
                string sql = @"
                    INSERT INTO GIWhere (CompanyID, DesignID, LineNbr, IsActive, OpenBrackets,
                        DataFieldName, Condition, IsExpression, Value1, CloseBrackets, Operation)
                    VALUES (2, @ID, @LineNbr, 1, 0, @DataFieldName, @Condition, 0, @Value1, 0, @Operation)";
                using (var cmd = new SqlCommand(sql, conn))
                {
                    cmd.Parameters.AddWithValue("@ID", designId);
                    cmd.Parameters.AddWithValue("@LineNbr", cond.LineNbr);
                    cmd.Parameters.AddWithValue("@DataFieldName", cond.DataFieldName);
                    cmd.Parameters.AddWithValue("@Condition", cond.Condition);
                    cmd.Parameters.AddWithValue("@Value1", cond.Value1);
                    cmd.Parameters.AddWithValue("@Operation", cond.Operation);
                    cmd.ExecuteNonQuery();
                }
            }
        }

        private void InsertSort(SqlConnection conn, Guid designId)
        {
            string sql = @"
                INSERT INTO GISort (CompanyID, DesignID, LineNbr, IsActive, DataFieldName, SortOrder)
                VALUES (2, @ID, 1, 1, 'AuditHistory.ChangeDate', 1)"; // 1 = Descending
            using (var cmd = new SqlCommand(sql, conn))
            {
                cmd.Parameters.AddWithValue("@ID", designId);
                cmd.ExecuteNonQuery();
            }
        }

        private void InsertFilters(SqlConnection conn, Guid designId)
        {
            var filters = new[]
            {
                new { LineNbr = 1, FieldName = "ScreenFilter", DisplayName = "Screen ID", DataType = 6 }, // 6 = string
                new { LineNbr = 2, FieldName = "FromDate", DisplayName = "From Date", DataType = 5 },     // 5 = datetime
                new { LineNbr = 3, FieldName = "ToDate", DisplayName = "To Date", DataType = 5 },
            };

            foreach (var filter in filters)
            {
                string sql = @"
                    INSERT INTO GIFilter (CompanyID, DesignID, LineNbr, IsActive, FieldName, DisplayName,
                        ColSpan, Required, DefaultValue, DataType)
                    VALUES (2, @ID, @LineNbr, 1, @FieldName, @DisplayName, 1, 0, '', @DataType)";
                using (var cmd = new SqlCommand(sql, conn))
                {
                    cmd.Parameters.AddWithValue("@ID", designId);
                    cmd.Parameters.AddWithValue("@LineNbr", filter.LineNbr);
                    cmd.Parameters.AddWithValue("@FieldName", filter.FieldName);
                    cmd.Parameters.AddWithValue("@DisplayName", filter.DisplayName);
                    cmd.Parameters.AddWithValue("@DataType", filter.DataType);
                    cmd.ExecuteNonQuery();
                }
            }
        }
    }
}
